// 排他制御のためなモデル
export default class LocksModel {
    constructor(flowUUID) {
        this.target = flowUUID;
    }
    Parse(data) {
        try {
            if (!data.data)
                throw "faild Parsing Data With undefined response.data(Post Locks Response)";
            let responseData = data.data;
            this.success = responseData.success;
            if (this.success) {
                this.lockId = (responseData.data) ? responseData.data.uuid : undefined;
            }
            else {
                this.error = {
                    code: responseData.code,
                    message: responseData.message
                };
            }
        }
        catch (e) {
            console.log(e);
        }
        finally {
            return this;
        }
    }
    getLockId() {
        return this.lockId;
    }
    setLockId(lockId) {
        this.lockId = lockId;
    }
    getErrorMessage() {
        let result = undefined;
        if (this.error && this.error.message)
            result = this.error.message;
        return result;
    }
    StatusText() {
        let result = "";
        try {
            result = "Flowの編集が可能な状態です。";
            if (this.success == false && this.error && this.error.message) {
                result = this.error.message;
            }
        }
        catch (e) {
            console.log(e);
        }
        return result;
    }
}
