import React from 'react';
import { ParamString, ParamBoolean, ParamSelect, ParamList } from 'Shared/Inspector/index';
import Constants from 'Constants/index';
import classnames from 'classnames';
import style from './style.scss';
export default class ParamsForm extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            helperTargetedInput: null
        };
    }
    setHelperTargetedInput(inputEl) {
        this.setState({
            helperTargetedInput: inputEl
        });
    }
    /**
     * 初期値 or 入力値の取得
     * @param args
     * @param param
     * @returns {*}
     */
    getDefaultValueOrArgsValue(args, param) {
        return args[param.name];
    }
    /**
     * コマンドの場合の必須判定
     * @param command
     * @param param
     * @returns {boolean}
     */
    isPresence(command, param) {
        let isPresence = false;
        if (command) {
            if (command.rules &&
                command.rules[param.name] &&
                command.rules[param.name]['presence']) {
                isPresence = true;
            }
        }
        return isPresence;
    }
    /**
     * 入力エラーメッセージの取得
     * @param invalid
     * @returns {*}
     */
    getInvalidMessageElement(invalid) {
        const invalidMessage = invalid;
        if (invalidMessage) {
            if (Array.isArray(invalidMessage)) {
                const arrayMessage = invalidMessage.map(message => {
                    return React.createElement("div", { className: style.invalid_message }, message);
                });
                return React.createElement("div", null, arrayMessage);
            }
            return React.createElement("div", { className: style.invalid_message }, invalidMessage);
        }
        return null;
    }
    getParamElement(param, disabled = false, label, value, onChange, headers) {
        let paramElement;
        let className = param.type === Constants.param.type.boolean ? classnames(style.param, style.flex) : style.param;
        try {
            switch (param.type) {
                case Constants.param.type.number:
                case Constants.param.type.string:
                    paramElement = React.createElement(ParamString, { label: label, param: param, disabled: disabled, value: value, helperTargetedInput: this.state.helperTargetedInput, helper: param.helper, setHelperTargetedInput: this.setHelperTargetedInput.bind(this), onChange: onChange });
                    break;
                case Constants.param.type.boolean:
                    paramElement = React.createElement(ParamBoolean, { label: label, param: param, disabled: disabled, value: value, onChange: onChange });
                    break;
                case Constants.param.type.select:
                    paramElement = React.createElement(ParamSelect, { label: label, param: param, disabled: disabled, value: value, onChange: onChange });
                    break;
                case Constants.param.type.column:
                    //カラム情報を付与
                    param.options = {
                        labels: headers,
                        values: headers,
                        multiple: (param.options && param.options.multiple) ? true : false
                    };
                    paramElement = React.createElement(ParamSelect, { label: label, param: param, disabled: disabled, value: value, onChange: onChange });
                    break;
                case Constants.param.type.list:
                    paramElement = React.createElement(ParamList, { label: label, param: param, disabled: disabled, value: value, helperTargetedInput: this.state.helperTargetedInput, headers: headers, helper: param.helper, setHelperTargetedInput: this.setHelperTargetedInput.bind(this), onChange: onChange });
                    break;
            }
        }
        catch (e) {
            console.log(e);
        }
        return React.createElement(React.Fragment, null,
            React.createElement("div", { className: className },
                React.createElement("div", { className: style.labelContainer },
                    React.createElement("div", { className: style.label }, param.label),
                    React.createElement("div", { className: style.description },
                        React.createElement("div", null, param.description))),
                paramElement));
    }
    renderGroup(group, key) {
        let className = group.hide_background ? style.group : classnames(style.group, style.colored);
        return React.createElement("div", { className: "mb-12px", key: key },
            React.createElement("div", { className: className }, group.label),
            React.createElement("div", { className: style.description }, group.description));
    }
    renderParam(param, key) {
        const { args, command, invalids, onChange, headers, disabled } = this.props;
        let isPresence = (command) ? this.isPresence(command, param) : false;
        const value = this.getDefaultValueOrArgsValue(args, param);
        const paramElement = this.getParamElement(param, disabled, param.label, value, onChange, headers);
        const invalidMessageEelement = this.getInvalidMessageElement(invalids[param.name]);
        return React.createElement("div", { key: key, className: classnames('mb-12px', {
                [style.presence]: isPresence,
                [style.invalid]: (invalidMessageEelement)
            }) },
            paramElement,
            invalidMessageEelement);
    }
    renderParamsForm(params, groups) {
        let paramsForm = [];
        try {
            if (!params)
                throw "params is undefined in renderParamsForm";
            if (groups) {
                groups.forEach(group => {
                    paramsForm.push(this.renderGroup(group, group.name + "_group"));
                    group.params.forEach((paramName, index) => {
                        const param = params.find(p => p.name == paramName);
                        if (!param)
                            throw "[Error] undefined params.name " + param.name + " in Group ";
                        const paramForm = this.renderParam(param, group.name + index);
                        paramsForm.push(paramForm);
                        params = params.filter(p => p.name !== paramName);
                    });
                });
            }
            if (params) {
                params.forEach((param, index) => {
                    const paramForm = this.renderParam(param, index);
                    paramsForm.push(paramForm);
                });
            }
        }
        catch (e) {
            console.log(e);
        }
        return paramsForm;
    }
    render() {
        const { params, groups } = this.props;
        //パラメータフォームの作成
        return this.renderParamsForm(params, groups);
    }
}
