import React from "react";
import ReactDOM from "react-dom";
import { Provider } from "react-redux";
import EventEmitter from "eventemitter3";
import store from "Modules/store/index";
import { Kskp, ViewId } from "./Kskp";
window.emitter = new EventEmitter();
let elementId = null;
let viewId = ViewId.Undefined;
if (document.getElementById("base")) {
    elementId = "base";
}
if (document.getElementById("flow_editor")) {
    elementId = "flow_editor";
    viewId = ViewId.Flow_Editor;
}
if (document.getElementById("project_list")) {
    elementId = "project_list";
    viewId = ViewId.Project_List;
}
if (document.getElementById("flow_list")) {
    elementId = "flow_list";
    viewId = ViewId.Flow_List;
}
if (document.getElementById("library")) {
    elementId = "library";
    viewId = ViewId.Library;
}
if (document.getElementById("profile")) {
    elementId = "profile";
    viewId = ViewId.Profile;
}
if (document.getElementById("preview")) {
    elementId = "preview";
    viewId = ViewId.Preview;
}
if (document.getElementById("trashcan")) {
    elementId = "trashcan";
    viewId = ViewId.TrashCan;
}
if (document.getElementById('trashcan')) {
    elementId = 'trashcan';
    viewId = ViewId.TrashCan;
}
if (document.getElementById('admin_users')) {
    elementId = 'admin_users';
    viewId = ViewId.User_List;
}
if (elementId) {
    ReactDOM.render(React.createElement(Provider, { store: store },
        React.createElement(Kskp, { viewId: viewId })), document.getElementById(elementId));
}
