import * as React from 'react';
import style from './style.scss';
import { useState } from 'react';
import { FilterCategoryItem } from 'Shared/Input/FilterListLinkButton/FilterCategoryItemList/FilterCategoryItem';
import { FilterListItem } from 'Shared/Input/FilterListLinkButton/FilterCategoryItemList/FilterListItem';
const FilterCategoryItemList = (props) => {
    const { list, onClickFilterCategoryItem, onClickFilterListItem } = props;
    const [selectedCategory, setSelectedCategory] = useState(null);
    const [selectedList, setSelectedList] = useState(null);
    const getInitialCheckedArray = () => {
        // list から 初期値でチェックが入っている ID を抽出する
        let initialChecked = [];
        list.forEach((categoryItem) => {
            if (categoryItem.multiple) {
                // 複数選択可能なカテゴリで、選択状態になっているもの
                categoryItem.data.forEach((listItem) => {
                    if (listItem.selected) {
                        initialChecked.push(listItem.id);
                    }
                });
            }
        });
        return initialChecked;
    };
    const [checkedArray, setCheckedArray] = useState(getInitialCheckedArray());
    // カテゴリ（一階層目）のクリック処理
    const _onClickCategoryItem = (categoryItem) => {
        setSelectedCategory(categoryItem);
        // 上位コンポーネントに通知
        onClickFilterCategoryItem(categoryItem);
    };
    // リスト（二階層目）が単一選択の場合の処理
    const _onClickListItem = (listItem) => {
        // 単一選択の場合
        setSelectedList(listItem);
        // 上位コンポーネントに通知
        onClickFilterListItem([listItem]);
    };
    // リスト（二階層目）が複数選択可能な場合の処理
    // checkedArray にて一時的なチェック状態を保持する
    const _onCheckedListItem = (listItem, checked) => {
        if (checked) {
            // チェックをつける
            // リストにない場合は、リストに追加してチェックボックスにチェックをいれる
            if (!checkedArray.includes(listItem.id)) {
                setCheckedArray([...checkedArray, listItem.id]);
            }
        }
        else {
            // チェックを外す
            setCheckedArray(checkedArray.filter(checkedId => {
                return !(listItem.id === checkedId);
            }));
        }
    };
    let listElement;
    if (!selectedCategory) {
        // カテゴリ（一階層目の表示）
        listElement = list.map((categoryItem, index) => {
            return React.createElement(FilterCategoryItem, { key: index, disabled: categoryItem.disabled, onClick: () => _onClickCategoryItem(categoryItem) }, categoryItem.label);
        });
    }
    else {
        // リスト（二階層目の表示）
        listElement = selectedCategory.data.map((filterItem, index) => {
            return React.createElement(FilterListItem, { key: index, onClick: () => _onClickListItem(filterItem), onChecked: (checked) => _onCheckedListItem(filterItem, checked), multiple: selectedCategory.multiple, selected: filterItem.selected, checked: checkedArray.includes(filterItem.id) }, filterItem.label);
        });
    }
    let applyElement;
    // 複数選択の場合
    if (selectedCategory && selectedCategory.multiple) {
        const onClickApply = () => {
            let checkedListItems = selectedCategory.data.filter((filterItem) => {
                const hasChecked = checkedArray.includes(filterItem.id);
                return hasChecked;
            });
            // チェックされたリストを selected を true にする
            checkedListItems = checkedListItems.map(checkedListItem => {
                return Object.assign(Object.assign({}, checkedListItem), { selected: true });
            });
            onClickFilterListItem(checkedListItems);
        };
        applyElement = React.createElement("div", { className: style.apply },
            React.createElement("a", { href: "javascript:void(0)", className: style.applyLink, onClick: onClickApply }, "\u9069\u7528"));
    }
    // 単一選択の場合
    return React.createElement("div", { className: style.categoryItemList },
        listElement,
        applyElement);
};
export { FilterCategoryItemList };
