import React, { useState } from "react";
import style from "./style.scss";
import { Command } from "FlowEditorContainer/Command";
import Constants from "Constants/index";
import { TextField } from "Shared/Input";
const CommandSelector = (props) => {
    const [keyword, setKeyword] = useState("");
    const onChangeKeyword = (e) => {
        setKeyword(e.target.value);
    };
    const sortArray = (array, key) => {
        return array.sort((objectA, objectB) => {
            const a = objectA[key];
            const b = objectB[key];
            let comparison = 0;
            if (a > b) {
                comparison = 1;
            }
            else if (a < b) {
                comparison = -1;
            }
            return comparison;
        });
    };
    /**
     * 複数個の入力ができるコマンド（入力ポートのtype が *）かどうか判定する
     * @param command
     * @returns {boolean}
     */
    const isMultiInPorts = (command) => {
        if (!command.getInPorts())
            return false;
        if (!command.getInPorts().length)
            return false;
        return (command.getInPorts()[0].name === "*");
    };
    const { numberOfInput, selected_step_ids, addStep, selectSteps, addHistory, disabled } = props;
    const isNoKeyword = (keyword.length == 0);
    let noOperators = true;
    let sortedCommands;
    let subflowSortedCommands;
    sortedCommands = sortArray(window.commands, "id");
    sortedCommands = sortArray(sortedCommands, "classification");
    subflowSortedCommands = sortArray(window.subflows, "label");
    sortedCommands = [...subflowSortedCommands, ...sortedCommands];
    //コマンドの絞り込み
    let operators = sortedCommands.filter((command) => {
        //if(numberOfInput && command.ports){
        if (isMultiInPorts(command)) {
            return true;
        }
        else if (command.getInPorts().length === numberOfInput) {
            return true;
        }
        //}
        return false;
    }).filter((command) => {
        noOperators = false;
        if (isNoKeyword) {
            return true;
        }
        const foundLabelWithKeyword = (command.label && command.label.indexOf(keyword) != -1);
        const foundDescriptionWithKeyword = (command.description && command.description.indexOf(keyword) != -1);
        const foundCommandIdWithKeyword = (command.id && command.id.indexOf(keyword) != -1);
        return (foundLabelWithKeyword || foundDescriptionWithKeyword || foundCommandIdWithKeyword);
    });
    let operatorsContainer = [];
    let beforeCommand = null;
    operators.map((command, index) => {
        if (!beforeCommand || beforeCommand.classification != command.classification) {
            //区切りを表示
            let label = Constants.lang.classification[command.classification];
            if (!label)
                label = command.classification;
            operatorsContainer.push(React.createElement("div", { key: command.id, className: style.command_separator }, label));
        }
        operatorsContainer.push(React.createElement(Command, { command: command, selected_step_ids: selected_step_ids, addStep: addStep, selectSteps: selectSteps, key: index, addHistory: addHistory }));
        beforeCommand = command;
    });
    let commandSelector;
    if (!noOperators) {
        commandSelector = React.createElement("div", null,
            React.createElement(TextField, { className: "mb-8px", onChange: (e) => onChangeKeyword(e), placeholder: "キーワード" }),
            React.createElement("div", { className: style.command_selector_container }, (operatorsContainer.length) ? operatorsContainer : React.createElement("div", { className: style.command_not_found }, "\u30B3\u30DE\u30F3\u30C9\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093\u3067\u3057\u305F")));
    }
    return React.createElement("div", null, commandSelector);
};
export { CommandSelector };
