import Model from "Model/Core";
export default class CommandModel extends Model {
    constructor(props) {
        super();
        this.classification = undefined;
        this.description = undefined;
        this.id = undefined;
        this.label = null;
        this.params = [];
        this.groups = undefined;
        this.ports = [[], []];
        this.rules = {};
        this.version = undefined;
        this.initialize(props, 'classification');
        this.initialize(props, 'description');
        this.initialize(props, 'id');
        this.initialize(props, 'label');
        this.initialize(props, 'params');
        this.initialize(props, 'groups');
        this.initialize(props, 'ports');
        this.initialize(props, 'version');
        this.initialize(props, 'rules');
    }
    getInPorts() {
        return this.ports[0];
    }
    getOutPorts() {
        return this.ports[1];
    }
    getParams() {
        return this.params;
    }
    getLabel() {
        return this.label;
    }
    getParam(key) {
        let result = {};
        this.params.find(param => {
            if (param.name === key)
                result = param;
        });
        return result;
    }
    isInPortsAddable() {
        let result = false;
        const ports = this.getInPorts();
        if (ports[0] && ports[0].name === '*')
            result = true;
        return result;
    }
    isOutPortsAddable() {
        let result = false;
        const ports = this.getOutPorts();
        if (ports[0] && ports[0].name === '*')
            result = true;
        return result;
    }
}
