import React from "react";
const Arrow = (props) => {
    const { x, y, width, height, angle, className } = props;
    return React.createElement("polygon", { points: x + "," + y + " " + (x - width / 2) + "," + (y - height) + " " + (x + width / 2) + "," + (y - height), className: className, transform: "rotate(" + angle + " " + x + " " + y + ")" });
};
export { Arrow };
