export const TYPE = {
    FOLDER: 'folder',
    AWSS3: 'awss3',
    RFOLDER: 'rfolder',
    DATABASE: 'database',
    FLOW: 'flow',
    FRAME: 'frame',
    TRASH: 'trash',
    UNDEFINED: 'undefined'
};
export default class LibraryModel {
    constructor(json) {
        this.uuid = json.uuid;
        this.type = json.type;
        this.label = json.label;
        this.creator = json.creator;
        this.createdAt = json.createdAt;
        this.children = json.children;
        this.folderPath = json.folderPath;
    }
    jsonToModel(json) {
        this.uuid = json.uuid;
        this.type = json.type;
        this.label = json.label;
        this.creator = json.creator;
        this.createdAt = json.createdAt;
        this.children = json.children;
        this.folderPath = json.folderPath;
    }
    modelToJson() {
        return {
            uuid: this.uuid,
            type: this.type,
            label: this.label,
            creator: this.creator,
            createdAt: this.createdAt,
            children: this.children,
            folderPath: this.folderPath
        };
    }
    isNotEmpty() {
        return (this.uuid) ? true : false;
    }
}
