import React, { useState } from "react";
import Constants from "Constants/index";
import { CommandStepModel, DataFrameStepModel, SubflowCommandModel, SubFlowStepModel } from "Model/index";
import style from "./style.scss";
import classnames from "classnames";
import CommandModel from "Model/Command/CommandModel";
import { CommandIcon, SubFlowIcon } from "Shared/SVG";
import { ParamUtil, WebUtil } from "Utils/index";
const Command = (props) => {
    const [inputRefs, setInputRefs] = useState([]);
    const onBuild = (param, element) => {
        if (element)
            setInputRefs([...inputRefs, { param: param, element: element }]);
    };
    const buildParamsContent = () => {
        const { command } = props;
        setInputRefs([]); //クリア
        let paramsInputs = command.params.map((param) => {
            const _onBuild = (param, element) => onBuild(param, element);
            let paramElement = ParamUtil.getParamElement(param, _onBuild);
            return React.createElement("div", { key: command.id + "_" + param.name, className: "mb-8px" }, paramElement);
        });
        if (!paramsInputs.length)
            paramsInputs = React.createElement("div", null, "\u3053\u306E\u30D5\u30ED\u30FC\u306B\u306F\u8A2D\u5B9A\u53EF\u80FD\u306A\u5909\u6570\u304C\u3042\u308A\u307E\u305B\u3093\u3002");
        const content = React.createElement("form", { onSubmit: onSubmitModal }, paramsInputs);
        return content;
    };
    const onSubmitModal = (e) => {
        e.preventDefault();
        //クリックされたときのEventEmitterを実行
        const id = Constants.modal.ADD_COMMAND;
        window.emitter.emit(Constants.event.MODAL_ON_CLICK_DONE + id, { id: id });
    };
    const getNewStepWithArgs = (command, args) => {
        let node;
        let model = {
            id: null,
            name: command.label,
            label: null,
            args: args
        };
        if (command instanceof CommandModel) {
            model.type = Constants.step.type.command;
            model.commandId = command.id;
            node = new CommandStepModel(model);
            node.initArgs();
        }
        else if (command instanceof SubflowCommandModel) {
            model.type = Constants.step.type.subflow;
            model.uuid = command.uuid;
            node = new SubFlowStepModel(model);
        }
        return node;
    };
    const onClickCommand = (e, command) => {
        const args = {};
        const added_command_step = getNewStepWithArgs(command, args);
        const { selected_step_ids, addStep, selectSteps, addHistory } = props;
        const output_steps = command.getOutPorts().map((port) => {
            const output_step = new DataFrameStepModel({
                id: null,
                label: null,
                type: Constants.step.type.frame,
                uuid: null,
                dataSource: Constants.data.dataSource.csv
            });
            addStep(output_step);
            return output_step;
        });
        const output_step_ids = output_steps.map(step => step.id);
        addStep(added_command_step, selected_step_ids, output_step_ids);
        //ステップの選択をキャンセル
        selectSteps();
        addHistory();
    };
    const onClickPdf = (e, url) => {
        window.open(url);
        e.preventDefault();
        e.stopPropagation();
    };
    const { command } = props;
    const iconClass = classnames(style.command_icon);
    let hasPdfLink = false;
    if (command.description) {
        hasPdfLink = (command.description.indexOf(".pdf") !== -1);
    }
    let description;
    if (hasPdfLink) {
        const url = WebUtil.webURL(command.description);
        description =
            React.createElement("a", { className: style.show_detail, href: "javascript:return false;", onClick: (e) => onClickPdf(e, url), onMouseDown: e => e.stopPropagation() }, "\u8A73\u7D30\u3092\u898B\u308B");
    }
    else {
        description = command.description;
    }
    let icon;
    if (command instanceof SubflowCommandModel) {
        icon = React.createElement(SubFlowIcon, null);
    }
    else {
        icon = React.createElement(CommandIcon, { command: command });
    }
    return React.createElement("div", { className: style.command, onClick: (e) => onClickCommand(e, command) },
        React.createElement("svg", { className: iconClass }, icon),
        React.createElement("div", { className: style.command_label_container },
            React.createElement("div", { className: style.command_label }, command.label),
            React.createElement("div", { className: style.command_description }, description)));
};
export { Command };
