import axios from 'axios';
export function Get(url, queryParam = {}) {
    return axios.get(url, (queryParam) ? { params: queryParam } : {});
}
export function Post(url, data, config = {}) {
    return axios.post(url, data, config);
}
export function Put(url, data, config = {}) {
    return axios.put(url, data, config);
}
export function Delete(url, queryParam = {}, data = {}) {
    const params = (queryParam) ? { params: queryParam } : {};
    const datas = { data } ? { data: data } : {};
    return axios.delete(url, Object.assign(Object.assign({}, params), datas));
}
